      Path(Line(Point(0, -250), Point(120, -170)), 55, 60, 1),
      Path(Line(Point(120, -170), Point(80, -60)), 60, 65, 1),
      Path(Line(Point(80, -60), Point(190, -20)), 65, 70, 1)
